export function solveVisualPreview(rawParams = {}) {
  const finite = (value, fallback) => Number.isFinite(Number(value)) ? Number(value) : fallback;
  const clamp = (value, low, high, fallback) => Math.min(Math.max(finite(value, fallback), low), high);
  const r = clamp(rawParams.visual_radial_scale_pct, 60, 160, 100) / 100;
  const az = clamp(rawParams.visual_axial_scale_pct, 60, 160, 100) / 100;
  const bz = az * clamp(rawParams.visual_body_axial_scale_pct, 60, 160, 100) / 100;
  const cz = az * clamp(rawParams.visual_cap_axial_scale_pct, 60, 160, 100) / 100;
  const turns = clamp(rawParams.visual_cap_unscrew_turns, 0, 3, 0);
  const extraLift = clamp(rawParams.visual_cap_extra_lift_mm, 0, 60, 0);
  const bodyColor = /^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(String(rawParams.visual_body_color || '')) ? String(rawParams.visual_body_color) : '#7097b3';
  const capColor = /^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(String(rawParams.visual_cap_color || '')) ? String(rawParams.visual_cap_color) : '#77b09a';
  const bodyOpacity = clamp(rawParams.visual_body_opacity, 0.10, 1, 1);
  const capOpacity = clamp(rawParams.visual_cap_opacity, 0.10, 1, 1);
  return { r, az, bz, cz, turns, extraLift, theta_deg: 360 * turns, cap_z_mm: 2 * turns + extraLift, bodyColor, capColor, bodyOpacity, capOpacity };
}

